import Auth from './Auth';

const ALL_POS = ["Pitcher","Catcher","1st Base","2nd Base","3rd Base","Shortstop","Left Field","Center Field","Right Field"];
const INFIELD  = ["Pitcher","Catcher","1st Base","2nd Base","3rd Base","Shortstop"];
const SKILLS   = ["Pitching","Catching","Infield Defense","Outfield Defense","Hitting Power","Hitting for Average","Speed / Baserunning","Arm Strength"];
const PS = {"Pitcher":"P","Catcher":"C","1st Base":"1B","2nd Base":"2B","3rd Base":"3B","Shortstop":"SS","Left Field":"LF","Center Field":"CF","Right Field":"RF"};
const FXY = {"Pitcher":{x:50,y:57},"Catcher":{x:50,y:87},"1st Base":{x:72,y:64},"2nd Base":{x:61,y:43},"3rd Base":{x:28,y:64},"Shortstop":{x:39,y:43},"Left Field":{x:18,y:22},"Center Field":{x:50,y:10},"Right Field":{x:82,y:22}};
const BST = [{key:"avg",label:"Batting Avg",hint:"0.325"},{key:"obp",label:"On-Base %",hint:"0.410"},{key:"rbi",label:"RBIs",hint:"12"},{key:"hr",label:"HRs",hint:"3"},{key:"era",label:"ERA (P)",hint:"2.45"},{key:"whip",label:"WHIP (P)",hint:"1.25"},{key:"k",label:"Ks (P)",hint:"34"},{key:"fpct",label:"Field %",hint:"0.965"}];
const SST = [{key:"avg",label:"Batting Avg",hint:"0.310"},{key:"obp",label:"On-Base %",hint:"0.390"},{key:"rbi",label:"RBIs",hint:"8"},{key:"hr",label:"HRs",hint:"2"},{key:"era",label:"ERA (P)",hint:"1.85"},{key:"whip",label:"WHIP (P)",hint:"1.12"},{key:"fpct",label:"Field %",hint:"0.972"}];

