// ── Sub-components ─────────────────────────────────────────────────────────

function DivBtn({k,cur,onSwitch}) {
  const d=DIVS[k], active=cur===k;
  return (
    <button onClick={()=>onSwitch(k)} style={{padding:"4px 9px",borderRadius:3,fontSize:11,fontFamily:"Georgia,serif",cursor:"pointer",textAlign:"center",lineHeight:1.5,whiteSpace:"nowrap",background:active?"#0f4fa8":"#1c2534",color:active?"#fff":"#c0d8f0",border:active?"1px solid #1a6fd4":"1px solid #1e3050"}}>
      <div style={{fontSize:11,fontWeight:active?700:400}}>{d.label}</div>
      <div style={{fontSize:9,opacity:0.8}}>{d.sub}</div>
    </button>
  );
}

function NavTab({label,active,onClick}) {
  return (
    <button onClick={onClick} style={{padding:"7px 12px",borderRadius:4,fontSize:13,fontWeight:700,fontFamily:"Georgia,serif",cursor:"pointer",background:active?"#0f4fa8":"transparent",color:active?"#fff":"#c0d8f0",border:active?"1px solid #1a6fd4":"1px solid #1e3050"}}>
      {label}
    </button>
  );
}

function FieldView({parsedInn,setParsedInn,fieldInn,setFieldInn,innings,showToast}) {
  const [lockedPos,setLockedPos]=useState({});      // {pos: playerName}
  const [swapFirst,setSwapFirst]=useState(null);    // pos waiting for swap partner
  const [dragPos,setDragPos]=useState(null);        // pos being dragged

  const inn=parsedInn[fieldInn]||{};

  // Update one position in the current inning
  // Swap two positions in current inning
  const swapPositions=(posA,posB)=>{
    const a=inn[posA]||"", b=inn[posB]||"";
    setParsedInn(prev=>({
      ...prev,
      [fieldInn]:{...(prev[fieldInn]||{}),[posA]:b,[posB]:a}
    }));
  };

  const handlePosClick=(pos)=>{
    if(!inn[pos]) return; // empty spot — nothing to do
    if(swapFirst===null){
      setSwapFirst(pos);
      showToast("Tap another position to swap with "+PS[pos]);
    } else if(swapFirst===pos){
      setSwapFirst(null); // cancel
    } else {
      if(lockedPos[swapFirst]||lockedPos[pos]){
        showToast("Can't swap — a position is locked 🔒");
        setSwapFirst(null);
        return;
      }
      swapPositions(swapFirst,pos);
      showToast(PS[swapFirst]+" ↔ "+PS[pos]+" swapped!");
      setSwapFirst(null);
    }
  };

  const handleDrop=(toPos)=>{
    if(!dragPos||dragPos===toPos) return;
    if(lockedPos[dragPos]||lockedPos[toPos]){
      showToast("Can't move — a position is locked 🔒");
      setDragPos(null); return;
    }
    swapPositions(dragPos,toPos);
    showToast(PS[dragPos]+" ↔ "+PS[toPos]+" swapped!");
    setDragPos(null);
  };

  const toggleLock=(pos)=>{
    if(!inn[pos]) return;
    if(lockedPos[pos]){
      setLockedPos(prev=>{const n={...prev};delete n[pos];return n;});
      showToast(PS[pos]+" unlocked");
    } else {
      setLockedPos(prev=>({...prev,[pos]:inn[pos]}));
      showToast(PS[pos]+" locked — won't be moved on next generate");
    }
  };

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:8,flexWrap:"wrap"}}>
        <span style={{fontSize:13,fontWeight:700,color:"#c0d8f0"}}>Inning:</span>
        {Array.from({length:innings},(_,i)=>i+1).map(n=>(
          <button key={n} onClick={()=>{setFieldInn(n);setSwapFirst(null);}} style={{width:34,height:34,borderRadius:"50%",fontWeight:700,fontSize:13,fontFamily:"Georgia,serif",cursor:"pointer",background:fieldInn===n?"#0f4fa8":"transparent",color:fieldInn===n?"#fff":"#c0d8f0",border:fieldInn===n?"2px solid #1a6fd4":"2px solid #1e3050"}}>{n}</button>
        ))}
      </div>
      <div style={{fontSize:12,color:"#4a6a8a",marginBottom:10,fontStyle:"italic"}}>
        Tap a player to quick-swap · Long-press drag to move · 🔒 to lock position
      </div>
      {swapFirst&&<div style={{background:"#0d1a2d",border:"1px solid #1a6fd4",borderRadius:6,padding:"6px 12px",marginBottom:8,fontSize:13,color:"#4a9aff",textAlign:"center"}}>
        Tap another position to swap with <b>{PS[swapFirst]} — {inn[swapFirst]}</b> · tap same to cancel
      </div>}
      <div style={{maxWidth:420,margin:"0 auto"}}>
        <svg viewBox="0 0 100 100" style={{width:"100%",height:"auto",display:"block"}}>
          <ellipse cx="50" cy="35" rx="47" ry="37" fill="#0d2a12" stroke="#0a1a0a" strokeWidth="0.5"/>
          <polygon points="50,88 73,63 50,38 27,63" fill="#3a2010" opacity="0.9"/>
          <polygon points="50,85 73,60 50,37 27,60" fill="none" stroke="#c8a855" strokeWidth="0.8"/>
          <rect x="47.5" y="82.5" width="5" height="5" fill="white" transform="rotate(45 50 85)"/>
          <rect x="70.5" y="57.5" width="5" height="5" fill="white" transform="rotate(45 73 60)"/>
          <rect x="47.5" y="34.5" width="5" height="5" fill="white" transform="rotate(45 50 37)"/>
          <rect x="24.5" y="57.5" width="5" height="5" fill="white" transform="rotate(45 27 60)"/>
          <circle cx="50" cy="62" r="3" fill="#3a2010" stroke="#8a6030" strokeWidth="0.5"/>
          <line x1="50" y1="85" x2="8"  y2="4"  stroke="#c8a855" strokeWidth="0.4" strokeDasharray="2,2" opacity="0.5"/>
          <line x1="50" y1="85" x2="92" y2="4"  stroke="#c8a855" strokeWidth="0.4" strokeDasharray="2,2" opacity="0.5"/>
          {ALL_POS.map(pos=>{
            const p=FXY[pos], name=inn[pos]||"", short=name?name.split(" ")[0].slice(0,5):"?";
            const isLocked=!!lockedPos[pos];
            const isSwapSel=swapFirst===pos;
            const isDragSrc=dragPos===pos;
            const fill=isSwapSel?"#1a6fd4":isDragSrc?"#2a5080":name?"#0f4fa8":"#1c2534";
            const stroke=isLocked?"#ffcc44":isSwapSel?"#88ccff":name?"#1a6fd4":"#1e3050";
            return (
              <g key={pos} style={{cursor:name?"pointer":"default"}}
                onClick={()=>handlePosClick(pos)}
                onDragStart={()=>{if(name)setDragPos(pos);}}
                onDragOver={e=>e.preventDefault()}
                onDrop={()=>handleDrop(pos)}
                draggable={!!name}
              >
                <circle cx={p.x} cy={p.y} r="7" fill={fill} stroke={stroke} strokeWidth={isLocked||isSwapSel?"1.4":"0.8"}/>
                <text x={p.x} y={p.y+0.8} textAnchor="middle" dominantBaseline="middle" fontSize="3.2" fill="#fff" fontWeight="700" fontFamily="monospace">{short}</text>
                <text x={p.x} y={p.y+9} textAnchor="middle" fontSize="2.6" fill="#4a9aff" fontFamily="monospace" fontWeight="700">{PS[pos]}</text>
                {isLocked&&<text x={p.x+5} y={p.y-4} fontSize="3.5" textAnchor="middle">🔒</text>}
              </g>
            );
          })}
        </svg>
      </div>
      {/* Position list with lock toggles */}
      <div style={{marginTop:12,display:"flex",flexWrap:"wrap",gap:6,justifyContent:"center"}}>
        {ALL_POS.map(pos=>{
          const isLocked=!!lockedPos[pos];
          return(
            <div key={pos} style={{background:isLocked?"#1a1400":"#1c2534",border:"1px solid "+(isLocked?"#5a4a00":"#1e3050"),borderRadius:4,padding:"4px 8px",fontSize:12,fontFamily:"monospace",display:"flex",alignItems:"center",gap:4}}>
              <span style={{color:"#4a9aff"}}>{PS[pos]}:</span>
              <span style={{color:"#e8f4ff"}}>{inn[pos]||"—"}</span>
              {inn[pos]&&(
                <button onClick={()=>toggleLock(pos)} title={isLocked?"Unlock position":"Lock position"} style={{background:"transparent",border:"none",cursor:"pointer",fontSize:12,padding:"0 2px",lineHeight:1}}>
                  {isLocked?"🔒":"🔓"}
                </button>
              )}
            </div>
          );
        })}
      </div>
      <div style={{marginTop:10,fontSize:12,color:"#4a6a8a",textAlign:"center"}}>
        🔒 Locked players stay at their position when you regenerate
      </div>
    </div>
  );
}

function Onboarding({onDone}) {
  const [step,setStep]=useState(0);
  const steps=[
    {icon:"🏟️",title:"Welcome to Total Lineup",body:"The AI-powered lineup generator for baseball and softball coaches. Smart, fast, and fair for every level of play."},
    {icon:"⚡",title:"How It Works",body:"Create your team, add players, mark who's present today, and tap Generate. Batting order, fielding rotations, and pitch counts — done in seconds."},
    {icon:"⚖️",title:"Rules Built In",body:"Little League infield minimums, once-pitcher rules, catcher pitch limits, and coed gender balance are all enforced automatically."},
  ];
  const s=steps[step];
  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.95)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:200,padding:20}}>
      <div style={{background:"#131920",border:"1px solid #1e3050",borderRadius:12,padding:36,width:"100%",maxWidth:420,textAlign:"center"}}>
        <img src={LOGO_URI} alt="Total Lineup" style={{height:60,width:"auto",display:"block",margin:"0 auto 20px"}}/>
        <div style={{fontSize:48,marginBottom:14}}>{s.icon}</div>
        <div style={{fontSize:19,fontWeight:700,color:"#e8f4ff",marginBottom:10}}>{s.title}</div>
        <div style={{fontSize:14,color:"#c0d8f0",lineHeight:1.7,marginBottom:24}}>{s.body}</div>
        <div style={{display:"flex",gap:6,justifyContent:"center",marginBottom:22}}>
          {steps.map((_,i)=><div key={i} style={{width:8,height:8,borderRadius:"50%",background:i===step?"#1a6fd4":"#1e3050"}}/>)}
        </div>
        <button onClick={()=>step<steps.length-1?setStep(s=>s+1):onDone()} style={{padding:"12px 0",width:"100%",borderRadius:6,fontSize:15,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer",fontFamily:"Georgia,serif"}}>
          {step<steps.length-1?"Next":"Create My First Team"}
        </button>
        {step>0&&<button onClick={()=>setStep(s=>s-1)} style={{marginTop:10,background:"transparent",border:"none",color:"#4a6a8a",fontSize:13,cursor:"pointer",fontFamily:"Georgia,serif"}}>Back</button>}
      </div>
    </div>
  );
}

