// ── Pitch Report Modal with Signature Pad ──────────────────────────────────
function PitchReportModal({ onClose, team, division, date, time, maxP, pitchers, restDays }) {
  const canvasRef = useRef(null);
  const [drawing, setDrawing] = useState(false);
  const [signed, setSigned] = useState(false);
  const lastPos = useRef(null);

  const getPos = (e, canvas) => {
    const rect = canvas.getBoundingClientRect();
    if (e.touches) {
      return { x: e.touches[0].clientX - rect.left, y: e.touches[0].clientY - rect.top };
    }
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const startDraw = (e) => {
    e.preventDefault();
    const canvas = canvasRef.current;
    const pos = getPos(e, canvas);
    setDrawing(true);
    lastPos.current = pos;
  };

  const draw = (e) => {
    e.preventDefault();
    if (!drawing) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const pos = getPos(e, canvas);
    ctx.beginPath();
    ctx.moveTo(lastPos.current.x, lastPos.current.y);
    ctx.lineTo(pos.x, pos.y);
    ctx.strokeStyle = "#1a6fd4";
    ctx.lineWidth = 2.5;
    ctx.lineCap = "round";
    ctx.stroke();
    lastPos.current = pos;
    setSigned(true);
  };

  const stopDraw = () => setDrawing(false);

  const clearSig = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setSigned(false);
  };

  const getReportLines = () => {
    const lines = [
      "================================================",
      "  LITTLE LEAGUE OFFICIAL PITCH COUNT REPORT",
      "  Generated by Total Lineup — totallineup.com",
      "================================================",
      "",
      `Team:        ${team}`,
      `Division:    ${division}`,
      `Date:        ${date}`,
      `Time:        ${time}`,
      `Pitch Limit: ${maxP} pitches`,
      "",
      "------------------------------------------------",
      "  PITCHER LOG",
      "------------------------------------------------",
      ""
    ];
    if (pitchers.length === 0) {
      lines.push("No pitches recorded yet.");
    } else {
      pitchers.forEach(p => {
        const status = maxP && p.pitchCount >= maxP ? "⚠️ AT LIMIT" : maxP && p.pitchCount >= maxP * 0.8 ? "⚠️ NEAR LIMIT" : "✅ OK";
        lines.push(`${p.name.padEnd(20)} #${(p.number || "?").toString().padStart(2, "0")}   ${p.pitchCount} pitches   ${status}`);
        lines.push(`  Rest: ${restDays(p.pitchCount)}`);
        lines.push("");
      });
    }
    lines.push("------------------------------------------------");
    lines.push("COMPLIANCE STATEMENT:");
    lines.push("I certify that the pitch counts above are accurate");
    lines.push("and that all Little League pitch count rules have");
    lines.push("been followed for this game.");
    lines.push("");
    lines.push("Coach Signature: [see below]");
    lines.push("");
    lines.push(`Date: ${date}`);
    lines.push("================================================");
    return lines.join("\n");
  };

  const handlePrint = () => {
    const sigData = signed ? canvasRef.current.toDataURL("image/png") : null;
    const pitcherRows = pitchers.length === 0
      ? "<tr><td colspan='4' style='text-align:center;color:#888'>No pitches recorded yet.</td></tr>"
      : pitchers.map(p => {
          const status = maxP && p.pitchCount >= maxP ? "⚠️ AT LIMIT" : maxP && p.pitchCount >= maxP * 0.8 ? "⚠️ NEAR LIMIT" : "✅ OK";
          return `<tr><td>${p.name}</td><td>#${(p.number||"?").toString().padStart(2,"0")}</td><td>${p.pitchCount}</td><td>${restDays(p.pitchCount)}</td><td>${status}</td></tr>`;
        }).join("");

    const sigImg = sigData ? ("<img src='" + sigData + "' height='80' style='border:1px solid #aaa;border-radius:4px;max-width:320px;' alt='Signature'/>") : "<em style='color:#888'>No signature provided</em>";
    const html = "<!DOCTYPE html><html><head><title>Pitch Count Report</title>"
      + "<style>body{font-family:Arial,sans-serif;max-width:700px;margin:40px auto;padding:20px;color:#111;}"
      + "h2{text-align:center;border-bottom:2px solid #1a6fd4;padding-bottom:8px;}"
      + "p.sub{text-align:center;font-size:12px;color:#555;}"
      + "table{width:100%;border-collapse:collapse;margin:16px 0;}"
      + "th{background:#1a6fd4;color:#fff;padding:8px;text-align:left;font-size:13px;}"
      + "td{padding:7px 8px;border-bottom:1px solid #ddd;font-size:13px;}"
      + ".info{font-size:13px;margin:4px 0;}"
      + ".box{background:#f5f5f5;border:1px solid #ccc;padding:14px;border-radius:4px;margin-top:20px;font-size:13px;}"
      + ".sigline{border-top:1px solid #333;width:320px;margin-top:8px;}"
      + "@media print{button{display:none;}}</style></head><body>"
      + "<h2>Little League Official Pitch Count Report</h2>"
      + "<p class='sub'>Generated by Total Lineup - totallineup.com</p>"
      + "<p class='info'><b>Team:</b> " + team + " &nbsp; <b>Division:</b> " + division + "</p>"
      + "<p class='info'><b>Date:</b> " + date + " &nbsp; <b>Time:</b> " + time + " &nbsp; <b>Pitch Limit:</b> " + maxP + " pitches</p>"
      + "<table><thead><tr><th>Player</th><th>#</th><th>Pitches</th><th>Rest Required</th><th>Status</th></tr></thead>"
      + "<tbody>" + pitcherRows + "</tbody></table>"
      + "<div class='box'><b>Compliance Statement:</b><br>I certify that the pitch counts above are accurate and that all Little League pitch count rules have been followed for this game.</div>"
      + "<div style='margin-top:20px;'><b>Coach Signature:</b><br>" + sigImg + "<div class='sigline'></div>"
      + "<div style='font-size:12px;margin-top:4px;'>Date: " + date + "</div></div>"
      + "<br><button onclick='window.print()' style='padding:10px 24px;background:#1a6fd4;color:#fff;border:none;border-radius:4px;font-size:15px;cursor:pointer;'>Print / Save as PDF</button>"
      + "</body></html>";
    const w = window.open("", "_blank");
    w.document.write(html);
    w.document.close();
    setTimeout(() => w.print(), 600);
  };

  const handleEmail = () => {
    const body = encodeURIComponent(getReportLines());
    const subject = encodeURIComponent(`Pitch Count Report — ${team} — ${date}`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.75)",zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:"#0d1f35",border:"1px solid #1e3050",borderRadius:10,width:"100%",maxwidth:800,maxHeight:"90vh",overflowY:"auto",padding:20}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div style={{fontWeight:700,fontSize:16,color:"#fff"}}>📋 Official Pitch Count Report</div>
          <button onClick={onClose} style={{background:"none",border:"none",color:"#aaa",fontSize:20,cursor:"pointer",lineHeight:1}}>✕</button>
        </div>

        {/* Report preview */}
        <div style={{background:"#0a1628",border:"1px solid #1e3050",borderRadius:6,padding:12,marginBottom:14,fontSize:12,fontFamily:"monospace",color:"#c8d8f0",whiteSpace:"pre-wrap",lineHeight:1.6}}>
          <div style={{color:"#4aaa4a",fontWeight:700}}>LITTLE LEAGUE OFFICIAL PITCH COUNT REPORT</div>
          <div style={{color:"#888",fontSize:11}}>Generated by Total Lineup — totallineup.com</div>
          <div style={{marginTop:8}}>
            <span style={{color:"#aaa"}}>Team: </span><span style={{color:"#fff"}}>{team}</span> &nbsp;
            <span style={{color:"#aaa"}}>Division: </span><span style={{color:"#fff"}}>{division}</span>
          </div>
          <div>
            <span style={{color:"#aaa"}}>Date: </span><span style={{color:"#fff"}}>{date}</span> &nbsp;
            <span style={{color:"#aaa"}}>Limit: </span><span style={{color:"#fff"}}>{maxP} pitches</span>
          </div>
          <div style={{borderTop:"1px solid #1e3050",marginTop:8,paddingTop:8}}>
            {pitchers.length === 0
              ? <div style={{color:"#888"}}>No pitches recorded yet.</div>
              : pitchers.map((p, i) => {
                  const status = maxP && p.pitchCount >= maxP ? "⚠️ AT LIMIT" : maxP && p.pitchCount >= maxP * 0.8 ? "⚠️ NEAR LIMIT" : "✅ OK";
                  return (
                    <div key={i} style={{marginBottom:6}}>
                      <span style={{color:"#fff",fontWeight:600}}>{p.name}</span>
                      <span style={{color:"#aaa"}}> #{(p.number||"?").toString().padStart(2,"0")} — </span>
                      <span style={{color:"#4aaa4a",fontWeight:700}}>{p.pitchCount} pitches</span>
                      <span style={{color:"#f0a500"}}> {status}</span>
                      <div style={{color:"#aaa",fontSize:11,marginLeft:8}}>{restDays(p.pitchCount)}</div>
                    </div>
                  );
                })
            }
          </div>
        </div>

        {/* Signature pad */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:12,color:"#aaa",marginBottom:6}}>Coach Signature <span style={{fontSize:11}}>(draw with finger or mouse)</span></div>
          <canvas
            ref={canvasRef}
            width={480}
            height={100}
            style={{width:"100%",height:100,background:"#fff",borderRadius:6,border:"2px solid #1e3050",cursor:"crosshair",display:"block",touchAction:"none"}}
            onMouseDown={startDraw}
            onMouseMove={draw}
            onMouseUp={stopDraw}
            onMouseLeave={stopDraw}
            onTouchStart={startDraw}
            onTouchMove={draw}
            onTouchEnd={stopDraw}
          />
          <button onClick={clearSig} style={{marginTop:6,fontSize:11,background:"none",border:"1px solid #1e3050",color:"#aaa",padding:"3px 10px",borderRadius:4,cursor:"pointer"}}>Clear</button>
        </div>

        {/* Action buttons */}
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <button onClick={handlePrint} style={{flex:1,padding:"10px 8px",background:"#1a6fd4",color:"#fff",border:"none",borderRadius:6,fontWeight:700,fontSize:13,cursor:"pointer"}}>🖨️ Print Report</button>
          <button onClick={handleEmail} style={{flex:1,padding:"10px 8px",background:"#1a5a1a",color:"#fff",border:"1px solid #2a8a2a",borderRadius:6,fontWeight:700,fontSize:13,cursor:"pointer"}}>📧 Email Report</button>
        </div>
      </div>
    </div>
  );
}

// ── Main App ───────────────────────────────────────────────────────────────
export default function App() {
  const [onboarding, setOnboarding] = useState(false);
  const [showSplash,  setShowSplash]  = useState(true);
  const [showPrivacy,setShowPrivacy] = useState(false);
  const [showPitchModal, setShowPitchModal] = useState(false);
  const [teams,      setTeams]       = useState([]);
  const [activeId,   setActiveId]    = useState(null);
  const [players,    setPlayers]     = useState([]);
  const [div,        setDiv]         = useState("bb_minors");
  const [seasonData, setSeasonData]  = useState({});
  const [lineupHist, setLineupHist]  = useState([]);
  const [lineup,     setLineup]      = useState(null);
  const [parsedInn,  setParsedInn]   = useState({});
  const [editedLU,   setEditedLU]    = useState(null);
  const [isEditing,  setIsEditing]   = useState(false);
  const [loading,    setLoading]     = useState(false);
  const [reevaling,  setReevaling]   = useState(false);
  const [reevalText, setReevalText]  = useState(null);
  const [rating,     setRating]      = useState(null);
  const [view,       setView]        = useState("roster");
  const [showForm,   setShowForm]    = useState(false);
  const [editIdx,    setEditIdx]     = useState(null);
  const [form,       setForm]        = useState(mkP());
  const [showTM,     setShowTM]      = useState(false);
  const [showNewT,   setShowNewT]    = useState(false);
  const [newTName,   setNewTName]    = useState("");
  const [newTDiv,    setNewTDiv]     = useState("bb_minors");
  const [editTId,    setEditTId]     = useState(null);
  const [editTName,  setEditTName]   = useState("");
  const [showSReset, setShowSReset]  = useState(false);
  const [showPReset, setShowPReset]  = useState(false);
  const [showHist,   setShowHist]    = useState(false);
  const [fieldInn,   setFieldInn]    = useState(1);
  const [dragIdx,    setDragIdx]     = useState(null);
  const [toast,      setToast]       = useState("");
  const [user, setUser] = useState(null);
  if (!user) return <Auth onLogin={() => setUser(true)} />;

  const sp=DIVS[div], activeTeam=teams.find(t=>t.id===activeId);
  const showToast=m=>{setToast(m);setTimeout(()=>setToast(""),3000);};
  const syncTeam=(tms,id,pl,dv,sd,lh)=>tms.map(t=>t.id===id?{...t,players:pl,div:dv,seasonData:sd,lineupHistory:lh}:t);

  const switchTeam=id=>{
    const saved=syncTeam(teams,activeId,players,div,seasonData,lineupHist); setTeams(saved);
    const t=saved.find(x=>x.id===id); if(!t) return;
    setActiveId(t.id); setPlayers([...(t.players||[])]); setDiv(t.div||"bb_minors");
    setSeasonData({...(t.seasonData||{})}); setLineupHist([...(t.lineupHistory||[])]);
    setLineup(null); setParsedInn({}); setEditedLU(null); setIsEditing(false);
    setReevalText(null); setRating(null); setView("roster");
    setShowTM(false); showToast("Switched to "+t.name);
  };

  const createTeam=()=>{
    if(!newTName.trim()) return;
    const saved=syncTeam(teams,activeId,players,div,seasonData,lineupHist);
    const t=mkT(newTName.trim(),newTDiv);
    setTeams([...saved,t]); setActiveId(t.id); setPlayers([]); setDiv(newTDiv);
    setSeasonData({}); setLineupHist([]);
    setLineup(null); setParsedInn({}); setEditedLU(null); setIsEditing(false);
    setReevalText(null); setRating(null); setView("roster");
    setNewTName(""); setNewTDiv("bb_minors"); setShowNewT(false); setShowTM(false);
    showToast(t.name+" created!");
  };

  const deleteTeam=id=>{
    const rest=teams.filter(t=>t.id!==id); setTeams(rest);
    if(activeId===id){
      if(rest.length>0){const t=rest[0];setActiveId(t.id);setPlayers([...(t.players||[])]);setDiv(t.div||"bb_minors");setSeasonData({...(t.seasonData||{})});setLineupHist([...(t.lineupHistory||[])]);}
      else{setActiveId(null);setPlayers([]);setSeasonData({});setLineupHist([]);}
      setLineup(null);setParsedInn({});setEditedLU(null);setView("roster");
    }
  };

  const saveTeamName=()=>{
    if(!editTName.trim()) return;
    setTeams(ts=>ts.map(t=>t.id===editTId?{...t,name:editTName.trim()}:t));
    setEditTId(null); setEditTName(""); showToast("Team name updated!");
  };

  const switchDiv=k=>{
    setDiv(k); setTeams(ts=>ts.map(t=>t.id===activeId?{...t,div:k}:t));
    setLineup(null); setParsedInn({}); setEditedLU(null); setIsEditing(false); setReevalText(null); setRating(null);
  };

  const upP=np=>{setPlayers(np);setTeams(ts=>ts.map(t=>t.id===activeId?{...t,players:np}:t));};
  const openAdd=()=>{setForm(mkP());setEditIdx(null);setShowForm(true);};
  const openEdit=i=>{const p=players[i];setForm({...p,skillSets:{...Object.fromEntries(SKILLS.map(s=>[s,5])),...(p.skillSets||{})}});setEditIdx(i);setShowForm(true);};
  const removeP=i=>upP(players.filter((_,idx)=>idx!==i));
  const saveP=()=>{
    if(!form.name.trim()) return;
    const np=editIdx!==null?players.map((pl,i)=>i===editIdx?{...form}:pl):[...players,{...form}];
    upP(np); setShowForm(false);
  };
  const togglePos=pos=>setForm(f=>({...f,preferredPositions:f.preferredPositions.includes(pos)?f.preferredPositions.filter(x=>x!==pos):[...f.preferredPositions,pos]}));
  const togglePresent=i=>upP(players.map((pl,idx)=>idx===i?{...pl,present:!pl.present}:pl));
  const updPitch=(id,v)=>upP(players.map(pl=>pl.id===id?{...pl,pitchCount:Math.max(0,v)}:pl));
  const resetPitches=()=>{upP(players.map(pl=>({...pl,pitchCount:0})));setShowPReset(false);showToast("Pitch counts reset!");};
  const hasStats=p=>p.stats&&Object.values(p.stats).some(v=>v!==""&&v!==undefined);
  const present=()=>players.filter(p=>p.present);

  const onDrop=(e,i)=>{
    e.preventDefault(); if(dragIdx===null||dragIdx===i) return;
    const r=[...players]; const[m]=r.splice(dragIdx,1); r.splice(i,0,m);
    upP(r); setDragIdx(null); showToast("Batting order updated");
  };

  const recordSeason=()=>{
    if(!Object.keys(parsedInn).length){showToast("Generate a lineup first!");return;}
    const updated={...seasonData};
    Object.values(parsedInn).forEach(innData=>Object.entries(innData).forEach(([pos,name])=>{
      if(!name||name==="Name") return;
      if(!updated[name]) updated[name]={};
      updated[name][pos]=(updated[name][pos]||0)+1;
    }));
    setSeasonData(updated); setTeams(ts=>ts.map(t=>t.id===activeId?{...t,seasonData:updated}:t)); showToast("Game recorded!");
  };

  const resetSeason=()=>{setSeasonData({});setTeams(ts=>ts.map(t=>t.id===activeId?{...t,seasonData:{}}:t));setShowSReset(false);showToast("Season data reset.");};

  const parseInn=text=>{
    const result={};
    for(const line of text.split("\n")){
      const m=line.match(/^INNING (\d+):/);
      if(m){
        const n=parseInt(m[1]); result[n]={};
        const rest=line.replace(/^INNING \d+:/,"");
        for(const pos of ALL_POS){
          const re=new RegExp(pos.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+":\\s*([^,\\n]+)");
          const pm=rest.match(re);
          if(pm){const name=pm[1].replace(/[[\]]/g,"").trim();if(name&&name!=="Name")result[n][pos]=name;}
        }
      }
    }
    return result;
  };

  const builtInLineup=()=>{
    const pp=present(); if(pp.length<2) return null;
    const batting=[...pp].sort((a,b)=>{const ao=parseFloat(a.stats?.obp)||0,bo=parseFloat(b.stats?.obp)||0;if(ao!==bo)return bo-ao;return b.skillLevel-a.skillLevel;});
    const posScore=(p,pos)=>{
      let s=p.skillLevel;
      if(p.preferredPositions.includes(pos)) s+=3;
      const sk=p.skillSets||{};
      if(pos==="Pitcher")      s+=(sk["Pitching"]||5)*0.5+(sk["Arm Strength"]||5)*0.2;
      if(pos==="Catcher")      s+=(sk["Catching"]||5)*0.5;
      if(INFIELD.includes(pos)&&pos!=="Pitcher"&&pos!=="Catcher") s+=(sk["Infield Defense"]||5)*0.4;
      if(!INFIELD.includes(pos)) s+=(sk["Outfield Defense"]||5)*0.4+(sk["Speed / Baserunning"]||5)*0.2;
      return s+Math.random()*0.4;
    };
    const innings={},IFC=Object.fromEntries(pp.map(p=>[p.name,0])),pitched={};
    for(let inn=1;inn<=sp.innings;inn++){
      innings[inn]={}; const assigned={};
      const pc=pp.filter(p=>!sp.noReturn||!pitched[p.name]).sort((a,b)=>posScore(b,"Pitcher")-posScore(a,"Pitcher"));
      const pitcher=pc[0]||pp[0];
      assigned["Pitcher"]=pitcher.name; pitched[pitcher.name]=true; IFC[pitcher.name]++;
      for(const pos of ALL_POS.filter(p=>p!=="Pitcher")){
        const rem=pp.filter(p=>!Object.values(assigned).includes(p.name)); if(!rem.length) break;
        let cands=[...rem];
        if(INFIELD.includes(pos)&&sp.minIF>0){const ni=cands.filter(p=>IFC[p.name]<sp.minIF);if(ni.length)cands=ni;}
        cands.sort((a,b)=>posScore(b,pos)-posScore(a,pos));
        assigned[pos]=cands[0].name;
        if(INFIELD.includes(pos)) IFC[cands[0].name]++;
      }
      innings[inn]=assigned;
    }
    const lines=["BATTING ORDER:"];
    batting.forEach((p,i)=>lines.push((i+1)+". "+p.name));
    lines.push("");
    for(let inn=1;inn<=sp.innings;inn++) lines.push("INNING "+inn+": "+ALL_POS.map(pos=>pos+":"+(innings[inn][pos]||"—")).join(", "));
    lines.push("");
    if(sp.minIF>0){lines.push("INFIELD INNINGS TRACKER:");pp.forEach(p=>lines.push(p.name+": "+(IFC[p.name]||0)+" infield innings"));lines.push("");}
    lines.push("PITCHING LOG:");
    [...new Set(Object.values(innings).map(inn=>inn["Pitcher"]))].forEach(name=>{
      const inns=Object.entries(innings).filter(([,pos])=>pos["Pitcher"]===name).map(([i])=>i);
      lines.push(name+": pitched inn. "+inns.join(", ")+" — one stint only");
    });
    lines.push("","COACH NOTES:");
    lines.push("Batting order by "+(pp.some(p=>p.stats?.obp)?"OBP":"skill level")+".");
    if(sp.noReturn) lines.push("Once-pitcher rule enforced.");
    if(sp.minIF>0){const short=pp.filter(p=>IFC[p.name]<sp.minIF);if(short.length)lines.push("Note: "+short.map(p=>p.name).join(", ")+" may need extra infield time.");else lines.push("All players meet minimum infield innings requirement.");}
    return{text:lines.join("\n"),innings};
  };

  const exportLineup=()=>{
    if(!lineup) return;
    const team=activeTeam?.name||"Team";
    const div=sp?.label||"";
    const date=new Date().toLocaleDateString();
    const text=[
      "TOTAL LINEUP EXPORT",
      "==================",
      `Team: ${team}`,
      `Division: ${div}`,
      `Date: ${date}`,
      `Players Present: ${present().length}`,
      "",
      lineup,
      "",
      "Generated by Total Lineup — totallineup.com"
    ].join("\n");
    const blob=new Blob([text],{type:"text/plain"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;
    a.download=`${team}-lineup-${date.replace(/\//g,"-")}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    showToast("Lineup exported! ✅");
  };

  const generateLineup=()=>{
    if(present().length<2){showToast("Need at least 2 present players!");return;}
    setLoading(true);setLineup(null);setParsedInn({});setEditedLU(null);setIsEditing(false);setReevalText(null);setRating(null);setView("lineup");
    setTimeout(()=>{
      try{
        const result=builtInLineup();
        if(result){
          setLineup(result.text);setEditedLU(result.text);setParsedInn(result.innings);
          const entry={id:Date.now(),date:new Date().toLocaleDateString(),time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),div,text:result.text,pc:present().length};
          const newH=[entry,...lineupHist].slice(0,10);
          setLineupHist(newH);setTeams(ts=>ts.map(t=>t.id===activeId?{...t,lineupHistory:newH}:t));
        }else setLineup("Could not generate — you need at least 9 players marked present to fill all positions.");
      }catch(err){setLineup("Error: "+err.message);}
      setLoading(false);
    },600);
  };

  const reevaluate=()=>{
    if(!lineup) return;
    const pp=present();
    if(pp.length<9){showToast("Need at least 9 present players to reevaluate ⚾");return;}
    setReevaling(true);
    setTimeout(()=>{
      const pp=present(); const lines=["REEVALUATION SUGGESTIONS:",""];
      pp.forEach(p=>{const sk=p.skillSets||{};const top=Object.entries(sk).sort(([,a],[,b])=>b-a)[0];const pref=p.preferredPositions[0];if(top&&top[1]>=7)lines.push(p.name+": Strong "+top[0]+" ("+top[1]+"/10)"+(pref?" — consider "+pref:"")+".");});
      if(pp.some(p=>p.stats?.obp)){const sorted=[...pp].sort((a,b)=>(parseFloat(b.stats?.obp)||0)-(parseFloat(a.stats?.obp)||0));lines.push("","BATTING ORDER BY OBP:");sorted.forEach((p,i)=>lines.push((i+1)+". "+p.name+" — OBP: "+(p.stats?.obp||"N/A")));}
      setReevalText(lines.join("\n"));setReevaling(false);
    },400);
  };

  const renderText=text=>text.split("\n").map((line,i)=>{
    if(!line.trim()) return <div key={i} style={{height:8}}/>;
    if(line.match(/^(BATTING ORDER|INNING \d+|INFIELD INNINGS TRACKER|PITCHING LOG|COACH NOTES|REEVALUATION):/))
      return <div key={i} style={{fontFamily:"monospace",fontSize:12,fontWeight:700,color:"#4a9aff",letterSpacing:"0.1em",textTransform:"uppercase",marginTop:18,marginBottom:5,borderBottom:"1px solid #1e3050",paddingBottom:4}}>{line}</div>;
    return <div key={i} style={{fontFamily:"monospace",fontSize:14,color:"#e8f4ff",lineHeight:1.85}}>{line}</div>;
  });

  const pCount=present().length, aCount=players.filter(p=>!p.present).length;

  return (
    <div style={{minHeight:"100vh",background:"#07090f",color:"#e8f4ff",fontFamily:"Georgia,serif",display:"flex",flexDirection:"column"}}>
      <style>{`
        *{box-sizing:border-box;margin:0;padding:0;}
        button{cursor:pointer;font-family:Georgia,serif;}
        input,select,textarea{outline:none;font-family:Georgia,serif;color:#e8f4ff;}
        input:focus,select:focus,textarea:focus{border-color:#1a6fd4!important;}
        ::-webkit-scrollbar{width:4px;}::-webkit-scrollbar-thumb{background:#1e3050;border-radius:2px;}
        .pc{background:#0d1117;border:1px solid #1e3050;border-radius:6px;padding:11px;display:flex;align-items:center;gap:9px;cursor:grab;}
        .pc:hover{border-color:#1a6fd4;}
        .ab{opacity:0.4;border-style:dashed!important;}
        .pt{padding:3px 8px;border-radius:3px;font-size:12px;border:1px solid;cursor:pointer;font-family:Georgia,serif;}
        .gb{padding:11px 22px;border:none;border-radius:6px;font-size:14px;font-weight:700;transition:all 0.2s;}
        .gb:hover:not(:disabled){filter:brightness(1.2);transform:translateY(-1px);}
        .gb:disabled{opacity:0.4;cursor:not-allowed;}
        .gl{font-size:10px;color:#c0d8f0;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px;}
        .tos{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#0d1a2d;border:1px solid #1a6fd4;color:#e8f4ff;padding:9px 18px;border-radius:6px;font-size:14px;z-index:300;pointer-events:none;white-space:nowrap;}
        .tc{background:#0d1117;border:1px solid #1e3050;border-radius:6px;padding:12px 14px;display:flex;align-items:center;gap:10px;}
        .tc:hover{border-color:#1a6fd4;}
        .mbg{position:fixed;inset:0;background:rgba(0,0,0,0.9);display:flex;align-items:center;justify-content:center;z-index:100;padding:20px;}
        .mbox{background:#131920;border:1px solid #1e3050;border-radius:10px;padding:24px;width:100%;max-height:92vh;overflow-y:auto;}
        .ibt{background:transparent;border:1px solid #1e3050;border-radius:4px;color:#c0d8f0;padding:5px 9px;font-size:13px;font-family:Georgia,serif;cursor:pointer;}
        .fi{background:#1c2534;border:1px solid #1e3050;border-radius:4px;color:#e8f4ff;padding:8px 11px;font-size:14px;width:100%;}
        .si{background:#131920;border:1px solid #1e3050;border-radius:4px;color:#e8f4ff;padding:6px 10px;font-size:14px;font-family:monospace;width:100%;}
        .fl{font-size:12px;color:#c0d8f0;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px;}
      `}</style>

      {onboarding&&<Onboarding onDone={()=>{setOnboarding(false);setShowSplash(false);setShowTM(true);}}/>}
      {toast&&<div className="tos">{toast}</div>}

      {/* SPLASH SCREEN */}
      {showSplash&&!onboarding&&(
        <div style={{position:"fixed",inset:0,zIndex:150,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",overflow:"hidden"}}>
          <img src={SPLASH_URI} alt="Total Lineup" style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",objectPosition:"center top"}}/>
          <div style={{position:"absolute",bottom:0,left:0,right:0,height:"35%",background:"linear-gradient(to bottom, transparent, rgba(7,9,15,0.97))"}}/>
          <div style={{position:"relative",zIndex:1,width:"100%",padding:"0 24px 48px",textAlign:"center"}}>
            {teams.length>0?(
              <>
                <button onClick={()=>setShowSplash(false)} style={{display:"block",width:"100%",maxWidth:320,margin:"0 auto",padding:"15px 0",borderRadius:6,fontSize:17,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer",fontFamily:"Georgia,serif"}}>
                  Go to My Teams
                </button>
                <button onClick={()=>setOnboarding(true)} style={{marginTop:12,background:"transparent",border:"none",color:"#c0d8f0",fontSize:14,cursor:"pointer",fontFamily:"Georgia,serif"}}>
                  View intro again
                </button>
              </>
            ):(
              <>
                <button onClick={()=>setOnboarding(true)} style={{display:"block",width:"100%",maxWidth:320,margin:"0 auto",padding:"15px 0",borderRadius:6,fontSize:17,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer",fontFamily:"Georgia,serif"}}>
                  Get Started
                </button>
                <div style={{fontSize:14,color:"#c0d8f0",marginTop:12,fontStyle:"italic"}}>Free 7-day trial · No credit card required</div>
              </>
            )}
          </div>
        </div>
      )}

      {/* HEADER */}
      <div style={{background:"#0d1117",borderBottom:"1px solid #1e3050",padding:"12px 18px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:8,marginBottom:activeId?12:0}}>
          <img src={LOGO_URI} alt="Total Lineup" style={{height:50,width:"auto",display:"block"}}/>
          <div style={{display:"flex",gap:7,flexWrap:"wrap",alignItems:"center"}}>
            {teams.length===0?(
              <button onClick={()=>setShowTM(true)} style={{padding:"8px 16px",borderRadius:5,fontSize:14,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none"}}>+ Create First Team</button>
            ):(
              <>
                <button onClick={()=>setShowTM(true)} style={{padding:"7px 12px",borderRadius:4,fontSize:13,fontWeight:700,background:"#1c2534",color:"#e8f4ff",border:"1px solid #1e3050"}}>
                  {activeTeam?"🏆 "+activeTeam.name:"Select Team"} ▾
                </button>
                <button className="ibt" onClick={()=>setShowTM(true)}>+ Teams</button>
              </>
            )}
            <button className="ibt" onClick={()=>{setShowSplash(true);}}>🏟️</button>
            <button className="ibt" onClick={()=>setOnboarding(true)}>❓</button>
            <button className="ibt" onClick={()=>setShowPrivacy(true)}>Privacy</button>
          </div>
        </div>
        {activeId&&(
          <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"flex-start"}}>
            <div><div className="gl">⚾ Baseball</div><div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{BBK.map(k=><DivBtn key={k} k={k} cur={div} onSwitch={switchDiv}/>)}</div></div>
            <div><div className="gl">🥎 Softball</div><div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{SBK.map(k=><DivBtn key={k} k={k} cur={div} onSwitch={switchDiv}/>)}</div></div>
          </div>
        )}
      </div>

      {/* Division info */}
      {activeId&&(
        <div style={{background:"#07090f",borderBottom:"1px solid #1e3050",padding:"5px 18px",display:"flex",gap:10,flexWrap:"wrap",alignItems:"center"}}>
          {sp.coed&&<span style={{background:"#1a0a2a",border:"1px solid #7a3aaa",color:"#cc88ff",padding:"1px 6px",borderRadius:10,fontSize:11,fontWeight:700}}>COED</span>}
          {sp.noReturn&&<span style={{background:"#1a0a0a",border:"1px solid #5a2222",color:"#ff8888",padding:"1px 6px",borderRadius:10,fontSize:11,fontWeight:700}}>Once-Pitcher Rule</span>}
          {[["Ages",sp.age],["Pitch",sp.pitch],["Bases",sp.bases],sp.maxP&&["Max P",""+sp.maxP]].filter(Boolean).map(([l,v])=>(
            <div key={l} style={{fontSize:12}}><span style={{color:"#c0d8f0",textTransform:"uppercase",letterSpacing:"0.06em"}}>{l}: </span><span style={{color:"#e8f4ff",fontWeight:700}}>{v}</span></div>
          ))}
        </div>
      )}

      {/* Nav */}
      {activeId&&(
        <div style={{background:"#07090f",borderBottom:"1px solid #1e3050",padding:"8px 18px",display:"flex",gap:5,flexWrap:"wrap"}}>
          <NavTab label={"Roster ("+pCount+"✓"+(aCount>0?" "+aCount+"✗":"")+")"} active={view==="roster"} onClick={()=>setView("roster")}/>
          <NavTab label="Lineup"      active={view==="lineup"} onClick={()=>setView("lineup")}/>
          <NavTab label="Field View"  active={view==="field"}  onClick={()=>setView("field")}/>
          <NavTab label="Pitch Count" active={view==="pitch"}  onClick={()=>setView("pitch")}/>
          <NavTab label="Season"      active={view==="season"} onClick={()=>setView("season")}/>
        </div>
      )}

      <div style={{flex:1,padding:"20px",maxWidth:900,width:"100%",margin:"0 auto"}}>

        {/* Welcome (no teams yet, splash dismissed) */}
        {!activeId&&!showSplash&&(
          <div style={{textAlign:"center",padding:"80px 20px"}}>
            <img src={LOGO_URI} alt="Total Lineup" style={{height:80,width:"auto",display:"block",margin:"0 auto 20px"}}/>
            <div style={{fontSize:15,color:"#c0d8f0",marginBottom:28,fontStyle:"italic"}}>Create your first team to get started.</div>
            <button onClick={()=>setShowTM(true)} style={{padding:"13px 32px",borderRadius:6,fontSize:15,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none"}}>+ Create Your First Team</button>
          </div>
        )}

        {/* ROSTER */}
        {activeId&&view==="roster"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
              <div>
                <div style={{fontSize:17,fontWeight:700}}>{activeTeam?.name} — Roster</div>
                <div style={{fontSize:13,color:"#c0d8f0",fontStyle:"italic",marginTop:2}}>Drag to reorder batting order · tap In/Out for attendance</div>
              </div>
              <button onClick={openAdd} style={{padding:"8px 16px",borderRadius:5,fontSize:13,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none"}}>+ Add Player</button>
            </div>

            {pCount>0&&pCount<sp.minP&&(
              <div style={{background:"#1a1400",border:"1px solid #4a3a00",borderRadius:6,padding:"8px 12px",fontSize:13,color:"#cc8833",marginBottom:8}}>
                Only {pCount} players present — {sp.minP} recommended for full fielding.
              </div>
            )}

            {players.length===0&&<div style={{textAlign:"center",padding:"60px 20px",color:"#1e3050",fontStyle:"italic"}}>No players yet — add your roster to get started.</div>}

            <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:22}}>
              {players.map((p,i)=>(
                <div key={p.id} className={"pc"+((!p.present)?" ab":"")} draggable onDragStart={()=>setDragIdx(i)} onDragOver={e=>e.preventDefault()} onDrop={e=>onDrop(e,i)}>
                  <div style={{color:"#1e3050",fontSize:18,flexShrink:0}}>⠿</div>
                  <div style={{background:p.present?"#0f4fa8":"#1c2534",border:p.present?"1px solid #1a6fd4":"1px solid #1e3050",borderRadius:5,width:42,height:42,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontWeight:700,fontSize:12,flexShrink:0,color:"#fff",lineHeight:1.2}}>
                    <div>{"#"+(p.number||"?")}</div>
                    {sp.coed&&p.gender&&<div style={{fontSize:9,opacity:0.7}}>{p.gender}</div>}
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontWeight:700,fontSize:14,display:"flex",alignItems:"center",gap:5,flexWrap:"wrap",color:"#e8f4ff"}}>
                      {p.name}
                      {hasStats(p)&&<span style={{fontSize:10,color:"#4a9aff",border:"1px solid #1a6fd4",borderRadius:3,padding:"1px 4px"}}>STATS</span>}
                      {!p.present&&<span style={{fontSize:10,color:"#ff4444",border:"1px solid #ff4444",borderRadius:3,padding:"1px 4px"}}>ABSENT</span>}
                      {p.notes&&<span style={{fontSize:10,color:"#cc8833",border:"1px solid #5a4a00",borderRadius:3,padding:"1px 4px"}}>📝</span>}
                    </div>
                    <div style={{fontSize:12,color:"#c0d8f0",marginTop:2}}>
                      {p.experience+" · Skill "+p.skillLevel+"/10"}
                      {p.preferredPositions.length>0?" · "+p.preferredPositions.slice(0,2).join(", "):""}
                      {p.pitchCount>0&&<span style={{color:sp.maxP&&p.pitchCount>=sp.maxP?"#ff2222":sp.maxP&&p.pitchCount>=sp.maxP*0.8?"#ff6b35":"#4a9aff"}}>{" · "+p.pitchCount+"p"}</span>}
                    </div>
                    {p.notes&&<div style={{fontSize:11,color:"#8a6a00",fontStyle:"italic",marginTop:2}}>📝 {p.notes}</div>}
                  </div>
                  <button onClick={()=>togglePresent(i)} style={{padding:"4px 9px",borderRadius:4,fontSize:11,fontWeight:700,border:"none",background:p.present?"#0a2a0a":"#2a0a0a",color:p.present?"#4aaa4a":"#aa4a4a"}}>{p.present?"✓ In":"✗ Out"}</button>
                  <button className="ibt" onClick={()=>openEdit(i)}>✏️</button>
                  <button className="ibt" onClick={()=>removeP(i)}>🗑️</button>
                </div>
              ))}
            </div>

            {pCount>=2?(
              <div style={{textAlign:"center"}}>
                <button className="gb" onClick={generateLineup} style={{background:"#1a6fd4",color:"#fff"}}>⚡ Generate Lineup ({pCount} players)</button>
                {aCount>0&&<div style={{marginTop:8,fontSize:13,color:"#ff6b35",fontStyle:"italic"}}>{aCount} player{aCount>1?"s":""} absent — excluded</div>}
              </div>
            ):players.length>0&&(
              <div style={{textAlign:"center",color:"#1e3050",fontStyle:"italic",fontSize:13}}>Mark at least 2 players as present to generate a lineup.</div>
            )}
          </div>
        )}

        {/* LINEUP */}
        {activeId&&view==="lineup"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,flexWrap:"wrap",gap:8}}>
              <div>
                <div style={{fontSize:17,fontWeight:700,color:"#e8f4ff"}}>{activeTeam?.name} — {sp.label}</div>
                <div style={{fontSize:13,color:"#c0d8f0",fontStyle:"italic"}}>{sp.sub}</div>
              </div>
              <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
                {lineup&&!loading&&<>
                  <button className="ibt" style={{background:isEditing?"#0f4fa8":"transparent",color:isEditing?"#fff":"#c0d8f0",borderColor:isEditing?"#1a6fd4":"#1e3050"}} onClick={()=>setIsEditing(e=>!e)}>{isEditing?"✓ Done":"✏️ Edit"}</button>
                  <button className="ibt" style={{color:reevaling?"#4a6a8a":"#cc8833",borderColor:reevaling?"#1e3050":"#5a4a00"}} onClick={reevaluate} disabled={reevaling}>{reevaling?"Analyzing...":"🔄 Reevaluate"}</button>
                  <button className="ibt" style={{color:"#4a9a4a",borderColor:"#1a4a1a"}} onClick={recordSeason}>📊 Record</button>
                  <button className="ibt" onClick={()=>setShowHist(true)}>🕐 History</button>
                  <button className="ibt" style={{color:"#4a9aff",borderColor:"#1a3a6a"}} onClick={exportLineup}>📤 Export</button>
                </>}
                <button className="gb" onClick={generateLineup} disabled={loading||pCount<2} style={{background:"#1a6fd4",color:"#fff",padding:"8px 14px",fontSize:13}}>{loading?"Generating...":"↻ Generate"}</button>
              </div>
            </div>

            {loading&&<div style={{textAlign:"center",padding:"60px 20px",color:"#c0d8f0",fontStyle:"italic"}}><div style={{fontSize:32,marginBottom:12}}>⏳</div>Building your optimal lineup...</div>}
            {!loading&&!lineup&&<div style={{textAlign:"center",padding:"60px 20px",color:"#1e3050",fontStyle:"italic"}}>Go to Roster and click Generate Lineup.</div>}

            {lineup&&!loading&&(
              isEditing
                ?<textarea value={editedLU||""} onChange={e=>{setEditedLU(e.target.value);setParsedInn(parseInn(e.target.value));}} style={{width:"100%",minHeight:360,background:"#131920",border:"1px solid #1a6fd4",borderRadius:8,padding:"18px",fontFamily:"monospace",fontSize:14,color:"#e8f4ff",lineHeight:1.85,resize:"vertical"}}/>
                :<div style={{background:"#131920",border:"1px solid #1e3050",borderRadius:8,padding:"20px 24px"}}>{renderText(editedLU||lineup)}</div>
            )}

            {lineup&&!loading&&(
              <div style={{marginTop:14,background:"#131920",border:"1px solid #1e3050",borderRadius:8,padding:"14px 18px",display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
                <div style={{fontSize:13,color:"#c0d8f0"}}>Rate this lineup:</div>
                <button onClick={()=>{setRating("up");showToast("Thanks!");}} className="ibt" style={{background:rating==="up"?"#0f4fa8":"transparent",color:rating==="up"?"#fff":"#4a9aff",borderColor:rating==="up"?"#1a6fd4":"#1e3050"}}>👍 Looks good</button>
                <button onClick={()=>{setRating("down");showToast("Thanks for the feedback!");}} className="ibt" style={{background:rating==="down"?"#2a0a0a":"transparent",color:rating==="down"?"#ff8888":"#c0d8f0",borderColor:rating==="down"?"#5a2222":"#1e3050"}}>👎 Needs work</button>
              </div>
            )}

            {reevalText&&!reevaling&&(
              <div style={{marginTop:14,background:"#131920",border:"1px solid #5a4a00",borderRadius:8,padding:"20px 24px"}}>
                <div style={{fontSize:12,fontWeight:700,color:"#cc8833",letterSpacing:"0.1em",textTransform:"uppercase",marginBottom:10,paddingBottom:6,borderBottom:"1px solid #3a2a00"}}>🔄 Reevaluation Suggestions</div>
                {renderText(reevalText)}
              </div>
            )}
          </div>
        )}

        {/* FIELD VIEW */}
        {activeId&&view==="field"&&(
          <div>
            <div style={{fontSize:17,fontWeight:700,marginBottom:14,color:"#e8f4ff"}}>{activeTeam?.name} — Field View</div>
            {!Object.keys(parsedInn).length
              ?<div style={{textAlign:"center",padding:"60px 20px",color:"#1e3050",fontStyle:"italic"}}>Generate a lineup first to see the field view.</div>
              :<FieldView parsedInn={parsedInn} setParsedInn={setParsedInn} fieldInn={fieldInn} setFieldInn={setFieldInn} innings={sp.innings} showToast={showToast}/>
            }
          </div>
        )}

        {/* PITCH COUNT */}
        {activeId&&view==="pitch"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,flexWrap:"wrap",gap:8}}>
              <div>
                <div style={{fontSize:17,fontWeight:700,color:"#e8f4ff"}}>{activeTeam?.name} — Pitch Count</div>
                {sp.maxP&&<div style={{fontSize:13,color:"#4a9aff",fontWeight:700,marginTop:2}}>League limit: {sp.maxP} pitches</div>}
              </div>
              <button className="ibt" style={{color:"#4a9aff"}} onClick={()=>setShowPReset(true)}>🔄 New Game Reset</button>
              {sp.maxP&&<button className="ibt" style={{color:"#4aaa4a",borderColor:"#1a5a1a"}} onClick={()=>setShowPitchModal(true)}>📋 Official Report</button>}
            </div>
            {!sp.maxP&&<div style={{fontSize:13,color:"#c0d8f0",fontStyle:"italic",marginBottom:14}}>No pitch limit for this division — tracking for reference only.</div>}
            {present().length===0&&<div style={{textAlign:"center",padding:"60px 20px",color:"#1e3050",fontStyle:"italic"}}>Add players to track pitch counts.</div>}
            <div style={{display:"flex",flexDirection:"column",gap:10}}>
              {present().map(p=>{
                const pct=sp.maxP?Math.min(100,(p.pitchCount/sp.maxP)*100):0;
                const atL=sp.maxP&&p.pitchCount>=sp.maxP, nrL=sp.maxP&&p.pitchCount>=sp.maxP*0.8;
                const clr=atL?"#ff2222":nrL?"#ff6b35":"#1a6fd4";
                return (
                  <div key={p.id} style={{background:"#131920",border:"1px solid "+(atL?"#ff2222":nrL?"#ff6b35":"#1e3050"),borderRadius:6,padding:"12px 14px"}}>
                    <div style={{marginBottom:sp.maxP?10:0}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
                        <div style={{fontWeight:700,fontSize:15,color:"#e8f4ff"}}>{p.name} <span style={{color:"#c0d8f0",fontWeight:400,fontSize:12}}>#{p.number||"?"}</span></div>
                        {atL&&<span style={{fontSize:11,color:"#ff2222",fontWeight:700,border:"1px solid #ff2222",borderRadius:3,padding:"2px 5px"}}>AT LIMIT</span>}
                        {nrL&&!atL&&<span style={{fontSize:11,color:"#ff6b35",fontWeight:700,border:"1px solid #ff6b35",borderRadius:3,padding:"2px 5px"}}>NEAR LIMIT</span>}
                      </div>
                      <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:12}}>
                        <button onClick={()=>updPitch(p.id,p.pitchCount-1)} style={{width:80,height:80,borderRadius:10,border:"1px solid #1e3050",background:"#1c2534",color:"#c0d8f0",fontSize:36,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center",touchAction:"manipulation",userSelect:"none"}}>−</button>
                        <div style={{width:90,textAlign:"center",background:"#131920",border:"2px solid "+clr,borderRadius:8,color:clr,padding:"10px 4px",fontSize:28,fontWeight:700,fontFamily:"monospace",userSelect:"none"}}>{p.pitchCount}</div>
                        <button onClick={()=>updPitch(p.id,p.pitchCount+1)} style={{width:80,height:80,borderRadius:10,border:"1px solid #1e3050",background:"#1c2534",color:clr,fontSize:36,fontWeight:700,display:"flex",alignItems:"center",justifyContent:"center",touchAction:"manipulation",userSelect:"none"}}>+</button>
                      </div>
                    </div>
                    {sp.maxP&&<div style={{background:"#1c2534",borderRadius:4,height:6,overflow:"hidden"}}><div style={{height:"100%",width:pct+"%",background:clr,borderRadius:4,transition:"width 0.2s"}}/></div>}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* SEASON */}
        {activeId&&view==="season"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6,flexWrap:"wrap",gap:8}}>
              <div>
                <div style={{fontSize:17,fontWeight:700,color:"#e8f4ff"}}>{activeTeam?.name} — Season Tracker</div>
                <div style={{fontSize:13,color:"#c0d8f0",fontStyle:"italic",marginTop:2}}>Cumulative innings per position. Prevents daddy ball.</div>
              </div>
              <button className="ibt" style={{color:"#aa4444",borderColor:"#5a2222"}} onClick={()=>setShowSReset(true)}>🗑 Reset Season</button>
            </div>
            {!Object.keys(seasonData).length?(
              <div style={{textAlign:"center",padding:"60px 20px",color:"#1e3050",fontStyle:"italic"}}>No data yet. Generate a lineup then click 📊 Record after each game.</div>
            ):(
              <div>
                <div style={{overflowX:"auto",marginTop:14}}>
                  <table style={{width:"100%",borderCollapse:"collapse",fontFamily:"monospace",fontSize:13}}>
                    <thead>
                      <tr>
                        <th style={{textAlign:"left",padding:"8px 10px",borderBottom:"2px solid #1a6fd4",color:"#4a9aff",fontWeight:700,whiteSpace:"nowrap"}}>Player</th>
                        {ALL_POS.map(pos=><th key={pos} style={{textAlign:"center",padding:"6px 5px",borderBottom:"2px solid #1a6fd4",color:"#4a9aff",fontSize:11,fontWeight:700,whiteSpace:"nowrap"}}>{PS[pos]}</th>)}
                        <th style={{textAlign:"center",padding:"6px 10px",borderBottom:"2px solid #1a6fd4",color:"#4a9aff",fontSize:11,fontWeight:700}}>Tot</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Object.entries(seasonData).sort(([a],[b])=>a.localeCompare(b)).map(([name,posData])=>{
                        const total=Object.values(posData).reduce((s,v)=>s+v,0), maxVal=Math.max(...Object.values(posData));
                        return <tr key={name} style={{borderBottom:"1px solid #1e3050"}}>
                          <td style={{padding:"8px 10px",color:"#e8f4ff",fontWeight:700,whiteSpace:"nowrap"}}>{name}</td>
                          {ALL_POS.map(pos=>{
                            const count=posData[pos]||0, isMax=count>0&&count===maxVal, isHigh=count>=4;
                            const hex=Math.min(count*20,99).toString(16).padStart(2,"0");
                            const bg=count===0?"transparent":"#0f4fa8"+hex;
                            const col=count===0?"#1e3050":isHigh?"#ff6b35":isMax?"#4a9aff":"#c0d8f0";
                            return <td key={pos} style={{textAlign:"center",padding:"6px 4px",background:bg,color:col,fontWeight:isMax||isHigh?700:400}}>{count||"·"}</td>;
                          })}
                          <td style={{textAlign:"center",padding:"6px 10px",color:"#c0d8f0",fontWeight:700}}>{total}</td>
                        </tr>;
                      })}
                    </tbody>
                  </table>
                </div>
                <div style={{marginTop:18}}>
                  <div style={{fontSize:13,fontWeight:700,color:"#cc8833",marginBottom:10,textTransform:"uppercase",letterSpacing:"0.08em"}}>Fairness Alerts</div>
                  {(()=>{
                    const alerts=[];
                    Object.entries(seasonData).forEach(([name,posData])=>{const total=Object.values(posData).reduce((s,v)=>s+v,0);if(total<3)return;Object.entries(posData).forEach(([pos,count])=>{if(count/total>0.6)alerts.push({name,pos,count,total,pct:Math.round(count/total*100)});});});
                    if(!alerts.length)return<div style={{fontSize:13,color:"#2a6a2a",fontStyle:"italic"}}>No fairness issues — positions distributed well!</div>;
                    return alerts.map((a,i)=>{
                      const key=`${a.name}-${a.pos}`;
                      if((sp.dismissedAlerts||[]).includes(key)) return null;
                      return <div key={i} style={{background:"#1a1500",border:"1px solid #5a4a00",borderRadius:6,padding:"9px 13px",marginBottom:8,fontSize:13,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                        <span>
                          <span style={{color:"#cc8833",fontWeight:700}}>{a.name}</span>
                          <span style={{color:"#c0d8f0"}}> played </span>
                          <span style={{color:"#ff6b35",fontWeight:700}}>{a.pos}</span>
                          <span style={{color:"#c0d8f0"}}> for {a.pct}% of innings ({a.count}/{a.total}).</span>
                        </span>
                        <button onClick={()=>setTeams(ts=>ts.map(t=>t.id===activeId?{...t,dismissedAlerts:[...(t.dismissedAlerts||[]),key]}:t))} style={{background:"transparent",border:"1px solid #5a4a00",borderRadius:4,color:"#8a7a4a",fontSize:11,padding:"2px 8px",cursor:"pointer",marginLeft:8,whiteSpace:"nowrap"}}>Ignore</button>
                      </div>;
                    });
                  })()}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* PITCH RESET MODAL */}
      {showPReset&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget)setShowPReset(false);}}>
          <div className="mbox" style={{maxWidth:360,textAlign:"center"}}>
            <div style={{fontSize:28,marginBottom:12}}>⚾</div>
            <div style={{fontSize:17,fontWeight:700,marginBottom:8,color:"#e8f4ff"}}>Reset Pitch Counts?</div>
            <div style={{fontSize:14,color:"#c0d8f0",marginBottom:8}}>Zeros all pitch counts for <span style={{color:"#e8f4ff",fontWeight:700}}>{activeTeam?.name}</span>.</div>
            <div style={{fontSize:13,color:"#c0d8f0",marginBottom:20,fontStyle:"italic"}}>Season tracking data is not affected.</div>
            <div style={{display:"flex",gap:10,justifyContent:"center"}}>
              <button className="ibt" onClick={()=>setShowPReset(false)}>Cancel</button>
              <button onClick={resetPitches} style={{padding:"8px 16px",borderRadius:4,background:"#0d1a2d",color:"#88aaff",border:"1px solid #2a4a8a",fontSize:14,fontWeight:700,cursor:"pointer",fontFamily:"Georgia,serif"}}>Reset for New Game</button>
            </div>
          </div>
        </div>
      )}

      {/* HISTORY MODAL */}
      {showHist&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget)setShowHist(false);}}>
          <div className="mbox" style={{maxWidth:500}}>
            <div style={{fontSize:17,fontWeight:700,marginBottom:14,color:"#e8f4ff"}}>Recent Lineups — {activeTeam?.name}</div>
            {lineupHist.length===0?(
              <div style={{color:"#1e3050",fontStyle:"italic",textAlign:"center",padding:"20px 0"}}>No lineups generated yet.</div>
            ):(
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {lineupHist.map(h=>(
                  <div key={h.id} style={{background:"#1c2534",border:"1px solid #1e3050",borderRadius:6,padding:"12px 14px"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                      <div>
                        <div style={{fontWeight:700,fontSize:14,color:"#e8f4ff"}}>{DIVS[h.div]?.label||h.div}</div>
                        <div style={{fontSize:12,color:"#c0d8f0",marginTop:2}}>{h.date} at {h.time} · {h.pc} players</div>
                      </div>
                      <button onClick={()=>{setLineup(h.text);setEditedLU(h.text);setParsedInn(parseInn(h.text));setRating(null);setView("lineup");setShowHist(false);showToast("Lineup loaded!");}} style={{padding:"5px 10px",borderRadius:3,fontSize:12,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer"}}>Load</button>
                    </div>
                    <div style={{fontFamily:"monospace",fontSize:11,color:"#c0d8f0",lineHeight:1.5,maxHeight:50,overflow:"hidden"}}>{h.text.split("\n").slice(0,3).join(" · ")}</div>
                  </div>
                ))}
              </div>
            )}
            <div style={{marginTop:14,display:"flex",justifyContent:"flex-end"}}><button className="ibt" onClick={()=>setShowHist(false)}>Close</button></div>
          </div>
        </div>
      )}

      {/* TEAM MANAGER MODAL */}
      {showTM&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget){setShowTM(false);setShowNewT(false);}}}>
          <div className="mbox" style={{maxWidth:480}}>
            <div style={{fontSize:18,fontWeight:700,marginBottom:16,color:"#e8f4ff"}}>🏆 My Teams</div>
            <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:16}}>
              {teams.length===0&&<div style={{color:"#1e3050",fontStyle:"italic",fontSize:14,textAlign:"center",padding:"20px 0"}}>No teams yet — create your first one below.</div>}
              {teams.map(team=>(
                <div key={team.id} className="tc" style={{borderColor:team.id===activeId?"#1a6fd4":"#1e3050"}}>
                  <div style={{width:10,height:10,borderRadius:"50%",background:team.id===activeId?"#1a6fd4":"#1e3050",flexShrink:0}}/>
                  <div style={{flex:1,minWidth:0}}>
                    {editTId===team.id?(
                      <div style={{display:"flex",gap:6}}>
                        <input value={editTName} onChange={e=>setEditTName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&saveTeamName()} className="fi" style={{padding:"4px 8px",fontSize:14,flex:1}}/>
                        <button onClick={saveTeamName} style={{padding:"4px 8px",borderRadius:3,background:"#1a6fd4",color:"#fff",border:"none",fontSize:13,fontWeight:700,cursor:"pointer"}}>✓</button>
                        <button className="ibt" onClick={()=>setEditTId(null)} style={{padding:"4px 8px",fontSize:13}}>✕</button>
                      </div>
                    ):(
                      <>
                        <div style={{fontWeight:700,fontSize:15,color:team.id===activeId?"#4a9aff":"#e8f4ff"}}>{team.name}{team.id===activeId?" ✓":""}</div>
                        <div style={{fontSize:12,color:"#c0d8f0",marginTop:1}}>{(DIVS[team.div]?.label||team.div)+" · "+(team.players?.length||0)+" players · "+team.createdAt}</div>
                      </>
                    )}
                  </div>
                  <div style={{display:"flex",gap:5,flexShrink:0}}>
                    {team.id!==activeId&&<button onClick={()=>switchTeam(team.id)} style={{padding:"5px 9px",borderRadius:3,fontSize:12,fontWeight:700,background:"#0f4fa8",color:"#fff",border:"1px solid #1a6fd4",cursor:"pointer"}}>Switch</button>}
                    <button className="ibt" onClick={()=>{setEditTId(team.id);setEditTName(team.name);}}>✏️</button>
                    <button className="ibt" style={{color:"#aa4444",borderColor:"#5a2222"}} onClick={()=>deleteTeam(team.id)}>🗑️</button>
                  </div>
                </div>
              ))}
            </div>
            {showNewT?(
              <div style={{background:"#1c2534",border:"1px solid #1e3050",borderRadius:8,padding:"16px"}}>
                <div style={{fontSize:15,fontWeight:700,marginBottom:12,color:"#e8f4ff"}}>Create New Team</div>
                <div className="fl">Team Name</div>
                <input className="fi" style={{marginBottom:12}} placeholder="e.g. Tigers 10U or Cubs 12U" value={newTName} onChange={e=>setNewTName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&createTeam()}/>
                <div className="fl" style={{marginBottom:6}}>Division</div>
                <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:14}}>
                  <div><div className="gl">⚾ Baseball</div><div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{BBK.map(k=><DivBtn key={k} k={k} cur={newTDiv} onSwitch={setNewTDiv}/>)}</div></div>
                  <div><div className="gl">🥎 Softball</div><div style={{display:"flex",gap:3,flexWrap:"wrap"}}>{SBK.map(k=><DivBtn key={k} k={k} cur={newTDiv} onSwitch={setNewTDiv}/>)}</div></div>
                </div>
                <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
                  <button className="ibt" onClick={()=>setShowNewT(false)}>Cancel</button>
                  <button onClick={createTeam} style={{padding:"7px 14px",borderRadius:4,fontSize:13,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer"}}>Create Team</button>
                </div>
              </div>
            ):(
              <button onClick={()=>setShowNewT(true)} style={{width:"100%",padding:"11px",borderRadius:6,fontSize:14,fontWeight:700,background:"transparent",color:"#4a9aff",border:"1px dashed #1a6fd4",cursor:"pointer",fontFamily:"Georgia,serif"}}>+ Add Team</button>
            )}
            <div style={{marginTop:14,display:"flex",justifyContent:"flex-end"}}><button className="ibt" onClick={()=>{setShowTM(false);setShowNewT(false);}}>Close</button></div>
          </div>
        </div>
      )}

      {/* SEASON RESET */}
      {showSReset&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget)setShowSReset(false);}}>
          <div className="mbox" style={{maxWidth:340,textAlign:"center"}}>
            <div style={{fontSize:28,marginBottom:12}}>⚠️</div>
            <div style={{fontSize:17,fontWeight:700,marginBottom:8,color:"#e8f4ff"}}>Reset Season Data?</div>
            <div style={{fontSize:14,color:"#c0d8f0",marginBottom:8}}>Permanently deletes season tracking for <span style={{color:"#e8f4ff",fontWeight:700}}>{activeTeam?.name}</span>.</div>
            <div style={{fontSize:13,color:"#c0d8f0",marginBottom:20,fontStyle:"italic"}}>Other teams not affected.</div>
            <div style={{display:"flex",gap:10,justifyContent:"center"}}>
              <button className="ibt" onClick={()=>setShowSReset(false)}>Cancel</button>
              <button onClick={resetSeason} style={{padding:"8px 16px",borderRadius:4,background:"#2a0a0a",color:"#ff8888",border:"1px solid #aa3333",fontSize:14,fontWeight:700,cursor:"pointer",fontFamily:"Georgia,serif"}}>Reset Season</button>
            </div>
          </div>
        </div>
      )}

      {/* PRIVACY */}
      {showPrivacy&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget)setShowPrivacy(false);}}>
          <div className="mbox" style={{maxWidth:500}}>
            <div style={{fontSize:18,fontWeight:700,marginBottom:4,color:"#e8f4ff"}}>Total Lineup Privacy Policy</div>
            <div style={{fontSize:12,color:"#c0d8f0",marginBottom:20}}>Effective: {new Date().toLocaleDateString()}</div>
            {[["Data We Collect","Total Lineup stores all data locally on your device only. We do not collect, transmit, or store any personal information on external servers."],["Children's Privacy","We do not collect any personal data from players or minors. All player data is stored only on the coach's device."],["AI Feature","The AI lineup generation feature uses the Anthropic Claude API. Anonymized roster data is sent to generate lineups. See anthropic.com/privacy."],["Contact","privacy@totallineup.com"]].map(([h,b])=>(
              <div key={h} style={{marginBottom:16}}>
                <div style={{fontSize:14,fontWeight:700,color:"#e8f4ff",marginBottom:4}}>{h}</div>
                <div style={{fontSize:13,color:"#c0d8f0",lineHeight:1.7}}>{b}</div>
              </div>
            ))}
            <button onClick={()=>setShowPrivacy(false)} style={{width:"100%",padding:"10px",borderRadius:6,fontSize:14,fontWeight:700,background:"#1c2534",color:"#c0d8f0",border:"1px solid #1e3050",cursor:"pointer",fontFamily:"Georgia,serif",marginTop:8}}>Close</button>
          </div>
        </div>
      )}

      {/* PLAYER FORM */}
      {showForm&&(
        <div className="mbg" onClick={e=>{if(e.target===e.currentTarget)setShowForm(false);}}>
          <div className="mbox" style={{maxWidth:560}}>
            <div style={{fontSize:17,fontWeight:700,marginBottom:18,color:"#e8f4ff"}}>{editIdx!==null?"Edit Player":"Add Player"} — {activeTeam?.name}</div>
            <SectionHead label="Player Info"/>
            <div style={{display:"grid",gridTemplateColumns:"1fr 76px",gap:10,marginBottom:12}}>
              <div><div className="fl">Name *</div><input className="fi" placeholder="Full name" value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))}/></div>
              <div><div className="fl">Jersey #</div><input className="fi" placeholder="#" value={form.number} onChange={e=>setForm(f=>({...f,number:e.target.value}))}/></div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:sp.coed?"1fr 1fr 90px":"1fr 1fr",gap:10,marginBottom:12}}>
              <div><div className="fl">Age</div><input className="fi" type="number" placeholder="Age" value={form.age} onChange={e=>setForm(f=>({...f,age:e.target.value}))}/></div>
              <div><div className="fl">Experience</div>
                <select className="fi" value={form.experience} onChange={e=>setForm(f=>({...f,experience:e.target.value}))}>
                  {["Beginner","Intermediate","Advanced","All-Star"].map(x=><option key={x}>{x}</option>)}
                </select>
              </div>
              {sp.coed&&<div><div className="fl">Gender</div>
                <select className="fi" value={form.gender||""} onChange={e=>setForm(f=>({...f,gender:e.target.value}))}>
                  <option value="">--</option><option value="M">Male</option><option value="F">Female</option>
                </select>
              </div>}
            </div>
            <div style={{marginBottom:12}}>
              <div className="fl" style={{marginBottom:0}}>Overall Skill: <span style={{color:"#4a9aff",fontWeight:700}}>{form.skillLevel}/10</span></div>
              <input type="range" min={1} max={10} value={form.skillLevel} onChange={e=>setForm(f=>({...f,skillLevel:+e.target.value}))} style={{width:"100%",accentColor:"#1a6fd4",marginTop:6}}/>
            </div>
            <div style={{marginBottom:12}}>
              <div className="fl" style={{marginBottom:8}}>Preferred Positions</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
                {ALL_POS.map(pos=>{const a=form.preferredPositions.includes(pos);return<button key={pos} className="pt" onClick={()=>togglePos(pos)} style={{background:a?"#0f4fa8":"transparent",color:a?"#fff":"#c0d8f0",borderColor:a?"#1a6fd4":"#1e3050"}}>{pos}</button>;})}
              </div>
            </div>
            <div style={{marginBottom:20}}>
              <div className="fl">Coach Notes</div>
              <textarea className="si" style={{resize:"vertical",minHeight:50,lineHeight:1.5}} placeholder="e.g. arm sore, leaves at 5pm, no pitching today" value={form.notes||""} onChange={e=>setForm(f=>({...f,notes:e.target.value}))}/>
            </div>
            <SectionHead label="Skill Ratings" sub="rate each 1-10"/>
            {SKILLS.map(skill=>{
              const val=(form.skillSets||{})[skill]??5, clr=val>=8?"#4a9aff":val<=3?"#aa4444":"#c0d8f0";
              return <div key={skill} style={{marginBottom:14}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                  <div style={{fontSize:14,color:"#e8f4ff",fontWeight:500}}>{skill}</div>
                  <div style={{fontSize:15,fontWeight:700,color:clr}}>{val}<span style={{fontSize:11,color:"#c0d8f0",fontWeight:400}}>/10</span></div>
                </div>
                <input type="range" min={1} max={10} value={val} onChange={e=>setForm(f=>({...f,skillSets:{...f.skillSets,[skill]:+e.target.value}}))} style={{width:"100%",accentColor:clr}}/>
                <div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:"#1e3050",marginTop:2}}><span>1 Beginner</span><span>5 Average</span><span>10 Elite</span></div>
              </div>
            })}
            <SectionHead label="Game Stats" sub="optional"/>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:8}}>
              {sp.stats.map(s=>{const k=s.key;return <div key={k}><div className="fl">{s.label}</div><input className="si" placeholder={s.hint} value={(form.stats||{})[k]||""} onChange={e=>{const v=e.target.value;setForm(f=>({...f,stats:{...f.stats,[k]:v}}));}}/>  </div>;})}
            </div>
            <div style={{display:"flex",gap:8,justifyContent:"flex-end",marginTop:20}}>
              <button className="ibt" onClick={()=>setShowForm(false)}>Cancel</button>
              <button onClick={saveP} style={{padding:"8px 16px",borderRadius:4,fontSize:14,fontWeight:700,background:"#1a6fd4",color:"#fff",border:"none",cursor:"pointer"}}>{editIdx!==null?"Save Changes":"Add Player"}</button>
            </div>
          </div>
        </div>
      )}

      {/* PITCH REPORT MODAL */}
      {showPitchModal && (
        <PitchReportModal
          onClose={()=>setShowPitchModal(false)}
          team={activeTeam?.name||"Team"}
          division={sp?.label||""}
          date={new Date().toLocaleDateString()}
          time={new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}
          maxP={sp?.maxP||"N/A"}
          pitchers={present().filter(p=>p.pitchCount>0).sort((a,b)=>b.pitchCount-a.pitchCount)}
          restDays={(count)=>{
            if(!sp?.maxP) return "N/A";
            if(count<=20) return "0 days rest required";
            if(count<=35) return "1 day rest required";
            if(count<=50) return "2 days rest required";
            if(count<=65) return "3 days rest required";
            return "4 days rest required";
          }}
        />
      )}

      {/* FOOTER */}
      <div style={{borderTop:"1px solid #1e3050",padding:"10px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:8,background:"#0d1117"}}>
        <div style={{fontSize:11,color:"#1e3050"}}>Total Lineup™ · Build Smarter Lineups. Win More.</div>
        <button className="ibt" style={{fontSize:11}} onClick={()=>setShowPrivacy(true)}>Privacy Policy</button>
      </div>
    </div>
  );
}
